Temporary debug output (answer scales):
{{
JSON.stringify(
  (AnswerScales.data || []).filter(
    row =>
      String(row.answer_scale_id) === String(
        (
          QuestionBank.data.find(
            q => String(q.question_id) === String(sel_question.selectedOptionValue)
          ) || {}
        ).answer_scale_id
      ) &&
      (
        String(row.active).toUpperCase() === "TRUE" ||
        row.active === true
      )
  ),
  null,
  2
)
}}

{{
(() => {
  const selectedQuestion = QuestionBank.data.find(
    q => String(q.question_id) === String(sel_question.selectedOptionValue)
  );

  if (!selectedQuestion) {
    return "Allowed answers will appear here.";
  }

  const responseType = String(selectedQuestion.response_type || "").toLowerCase();

  if (!["categorical", "boolean"].includes(responseType)) {
    return "Enter a numeric value.";
  }

  const options = (AnswerScales.data || [])
    .filter(row =>
      String(row.answer_scale_id) === String(selectedQuestion.answer_scale_id) &&
      (String(row.active).toUpperCase() === "TRUE" || row.active === true)
    )
    .sort((a, b) => Number(a.display_order || 999) - Number(b.display_order || 999))
    .map(row => row.answer_option);

  if (!options.length) {
    return "No allowed answers found.";
  }

  return "Allowed answers (enter exactly as shown): " + options.join(" | ");
})()
}}

