temp debug output (multiplier rule): 
{{
(() => {
  const selectedQuestion = (QuestionBank.data || []).find(
    q => String(q.question_id) === String(sel_question.selectedOptionValue)
  );

  const selectedSME = (NocoDB.data?.list || []).find(
    row => String(row.test_id) === String(sel_test_sme.selectedOptionValue)
  );

  if (!selectedQuestion) {
    return "No question selected";
  }

  if (!selectedSME) {
    return "No SME selected";
  }

  const questionTags = String(selectedQuestion.tags || "")
    .split(";")
    .map(s => s.trim().toLowerCase())
    .filter(Boolean);

  const questionCategory = String(selectedQuestion.category || "").trim().toLowerCase();
  const questionSubcategory = String(selectedQuestion.subcategory || "").trim().toLowerCase();

  const smeIndustry = String(selectedSME.industry || "").trim().toLowerCase();
  const smeRegion = String(selectedSME.target_market_region || "").trim().toLowerCase();
  const smeBuyer = String(selectedSME.target_buyer || "").trim().toLowerCase();
  const smeGoal = String(selectedSME.business_goal || "").trim().toLowerCase();

  const matches = (MultiplierRules.data || []).filter(rule => {
    const activeOk =
      String(rule.active).toUpperCase() === "TRUE" || rule.active === true;

    if (!activeOk) return false;

    const ruleTag = String(rule.tag || "").trim().toLowerCase();
    const ruleCategory = String(rule.category || "").trim().toLowerCase();
    const ruleSubcategory = String(rule.subcategory || "").trim().toLowerCase();
    const ruleIndustry = String(rule.industry || "").trim().toLowerCase();
    const ruleRegion = String(rule.target_market_region || "").trim().toLowerCase();
    const ruleBuyer = String(rule.target_buyer || "").trim().toLowerCase();
    const ruleGoal = String(rule.business_goal || "").trim().toLowerCase();

    const tagOk =
      ruleTag === "any" ||
      ruleTag === "" ||
      questionTags.includes(ruleTag);

    const categoryOk =
      ruleCategory === "any" ||
      ruleCategory === "" ||
      ruleCategory === questionCategory;

    const subcategoryOk =
      ruleSubcategory === "any" ||
      ruleSubcategory === "" ||
      ruleSubcategory === questionSubcategory;

    const industryOk =
      ruleIndustry === "any" ||
      ruleIndustry === "" ||
      ruleIndustry === smeIndustry;

    const regionOk =
      ruleRegion === "any" ||
      ruleRegion === "" ||
      smeRegion.includes(ruleRegion);

    const buyerOk =
      ruleBuyer === "any" ||
      ruleBuyer === "" ||
      smeBuyer.includes(ruleBuyer);

    const goalOk =
      ruleGoal === "any" ||
      ruleGoal === "" ||
      smeGoal.includes(ruleGoal);

    return tagOk && categoryOk && subcategoryOk && industryOk && regionOk && buyerOk && goalOk;
  });

  return JSON.stringify(matches, null, 2);
})()
}}

