children.text:
{{
(() => {
  const responseType = String(currentItem.response_type || "").trim().toLowerCase();
  const answerScaleId = String(currentItem.answer_scale_id || "").trim();

  if (responseType === "percent") {
    return "Allowed format: enter 10% as 10.";
  }

  if (responseType === "numeric") {
    return "Allowed format: numeric value only.";
  }

  if (!["categorical", "boolean"].includes(responseType)) {
    return "DEBUG → Unsupported response_type: " + responseType;
  }

  const matches = (AnswerScales.data || [])
    .filter(row =>
      String(row.answer_scale_id || "").trim() === answerScaleId &&
      (
        String(row.active || "").trim().toUpperCase() === "TRUE" ||
        row.active === true ||
        String(row.active || "").trim() === "" ||
        row.active == null
      )
    )
    .sort((a, b) => Number(a.display_order || 999) - Number(b.display_order || 999));

  if (!matches.length) {
    return "DEBUG → No AnswerScales match for answer_scale_id = " + answerScaleId + " | response_type = " + responseType;
  }

  return "Allowed answers (enter exactly as shown): " + matches.map(row => row.answer_option).join(" | ");
})()
}}

