function (question, rawAnswer) {
  if (!question) return {
    error: "No question selected"
  };
  const responseType = ScoringEngine.normalizeText(question.response_type);
  if (["categorical", "boolean"].includes(responseType)) {
    const matchedScaleRow = ScoringEngine.getAnswerScaleRow(question, rawAnswer);
    if (!matchedScaleRow) return {
      error: "No matching answer option found"
    };
    return {
      value: Number(matchedScaleRow.normalized_score),
      method: "answer_scale"
    };
  }
  if (["numeric", "percent"].includes(responseType)) {
    const x = Number(rawAnswer);
    if (isNaN(x)) return {
      error: "Invalid numeric input"
    };
