actionConfiguration.body:
function (question, rawAnswer) {
  if (!question) return {
    error: "No question provided"
  };
  const responseType = AssessmentScoring.normalizeText(question.response_type);
  if (rawAnswer === null || rawAnswer === undefined || String(rawAnswer).trim() === "") {
    return {
      error: "No answer provided"
    };
  }
  if (["categorical", "boolean"].includes(responseType)) {
    const matchedScaleRow = AssessmentScoring.getAnswerScaleRow(question, rawAnswer);
    if (!matchedScaleRow) return {
      error: "No matching answer option found"
    };
    return {
      value: Number(matchedScaleRow.normalized_score),
      method: "answer_scale"
    };
  }
  if (["numeric", "percent"].includes(responseType)) {
    const x = Number(rawAnswer);
    if (isNaN(x)) return {
      error: "Invalid numeric input"
    };
    const metric = AssessmentScoring.getMetric(question);
    if (!metric) return {
      error: "No metric benchmark found"
    };
    const method = AssessmentScoring.getMethod(metric);
    const p1 = AssessmentScoring.toNumber(metric.param_1);
    const p2 = AssessmentScoring.toNumber(metric.param_2);
    const p3 = AssessmentScoring.toNumber(metric.param_3);
    const minValue = AssessmentScoring.toNumber(metric.min_value);
    const maxValue = AssessmentScoring.toNumber(metric.max_value);
    const safeMax = Number.isFinite(maxValue) && maxValue !== 0 ? maxValue : 100;
    let score01;
    if (method === "identity_percent" || method === "percent_direct") {
      const capped = AssessmentScoring.clamp(x, 0, safeMax);
      return {
        value: Number(capped.toFixed(2)),
        method
      };
    }
    if (method === "identity_boolean") {
      return {
        value: x,
        method
      };
    }
    if (method === "gaussian" || method === "gaussian_target") {
      if (isNaN(p1) || isNaN(p2) || p2 === 0) {
        return {
          error: "Invalid gaussian parameters"
        };
      }
      const z = (x - p1) / p2;
      score01 = Math.exp(-0.5 * Math.pow(z, 2));
      return {
        value: Number((score01 * safeMax).toFixed(2)),
        method
      };
    }
    if (method === "linear_cap" || method === "linear_cap_benchmark") {
      if (isNaN(p1) || p1 === 0) {
        return {
          error: "Invalid linear_cap threshold"
        };
      }
      score01 = Math.min(x / p1, 1);
      return {
        value: Number((score01 * safeMax).toFixed(2)),
        method
      };
    }
    if (method === "inverse_count") {
      score01 = 1 / (1 + x);
      return {
        value: Number((score01 * safeMax).toFixed(2)),
        method
      };
    }
    if (method === "inverse_percentage" || method === "percent_inverse") {
      const cappedInput = AssessmentScoring.clamp(x, 0, 100);
      score01 = 1 - cappedInput / 100;
      score01 = AssessmentScoring.clamp(score01, 0, 1);
      return {
