actionConfiguration.body:
function (question) {
  const sme = AssessmentScoring.getSelectedSME();
  if (!question) return {
    error: "No question selected"
  };
  if (!sme) return {
    error: "No SME selected"
  };
  const questionTags = Array.isArray(question.tags) ? question.tags.map(t => String(t).trim().toLowerCase()).filter(Boolean) : String(question.tags || "").split(/[;,]/).map(s => s.trim().toLowerCase()).filter(Boolean);
  const questionCategory = AssessmentScoring.normalizeText(question.category);
  const questionSubcategory = AssessmentScoring.normalizeText(question.subcategory);
  const smeIndustry = AssessmentScoring.normalizeText(sme.industry);
  const smeRegion = AssessmentScoring.normalizeText(sme.target_market_region);
  const smeBuyer = AssessmentScoring.normalizeText(sme.target_buyer);
  const smeGoal = AssessmentScoring.normalizeText(sme.business_goal);
  const matches = (MultiplierRules.data || []).filter(rule => {
    const rawActive = String(rule.active ?? "").trim().toUpperCase();
    if (!(rawActive === "TRUE" || rawActive === "YES" || rawActive === "1")) return false;
    const ruleTags = String(rule.tag || "").split(/[;,]/).map(s => s.trim().toLowerCase()).filter(Boolean);
    const ruleCategory = AssessmentScoring.normalizeText(rule.category);
    const ruleSubcategory = AssessmentScoring.normalizeText(rule.subcategory);
    const ruleIndustry = AssessmentScoring.normalizeText(rule.industry);
    const ruleRegion = AssessmentScoring.normalizeText(rule.target_market_region);
    const ruleBuyer = AssessmentScoring.normalizeText(rule.target_buyer);
    const ruleGoal = AssessmentScoring.normalizeText(rule.business_goal);
    const tagOk = ruleTags.length === 0 || ruleTags.includes("any") || ruleTags.some(rt => questionTags.includes(rt));
    const categoryOk = ruleCategory === "" || ruleCategory === "any" || ruleCategory === questionCategory;
    const subcategoryOk = ruleSubcategory === "" || ruleSubcategory === "any" || ruleSubcategory === questionSubcategory;
    const industryOk = ruleIndustry === "" || ruleIndustry === "any" || ruleIndustry === smeIndustry;
    const regionOk = ruleRegion === "" || ruleRegion === "any" || smeRegion.includes(ruleRegion);
    const buyerOk = ruleBuyer === "" || ruleBuyer === "any" || smeBuyer.includes(ruleBuyer);
    const goalOk = ruleGoal === "" || ruleGoal === "any" || smeGoal.includes(ruleGoal);
    return tagOk && categoryOk && subcategoryOk && industryOk && regionOk && buyerOk && goalOk;
  });
  const rawMultiplier = matches.reduce((acc, rule) => {
    const m = Number(rule.multiplier);
    return acc * (isNaN(m) ? 1 : m);
  }, 1);
  return {
    value: Math.min(rawMultiplier, 1.5),
    matched_rules: matches.map(rule => ({
      rule_id: rule.rule_id,
      tag: rule.tag,
      category: rule.category,
      subcategory: rule.subcategory,
      industry: rule.industry,
      target_market_region: rule.target_market_region,
      target_buyer: rule.target_buyer,
      business_goal: rule.business_goal,
      multiplier: rule.multiplier
    }))
  };
}

