actionConfiguration.body:
function () {
  const weights = AssessmentScoring.getCategoryWeights();
  const categories = AssessmentScoring.getCategoryScores();
  if (!categories || !categories.length) {
    return {
      weighted_score: 0,
      max_score: 100,
      weights_found: false,
      industry: dd_industry.selectedOptionValue || "",
      breakdown: []
    };
  }
  const weightMap = {
    People: weights?.people_weight ?? 0,
    Governance: weights?.governance_weight ?? 0,
    Community: weights?.community_weight ?? 0,
    Resources: weights?.resources_weight ?? 0
  };
  const breakdown = categories.map(c => {
    const percent = Number(c.category_percent || 0);
    const weight = Number(weightMap[c.category] || 0);
    const contribution = percent * weight;
    return {
      category: c.category,
      raw_percent: percent,
      weight: weight,
      weighted_contribution: contribution
    };
  });
  const weightedScore = breakdown.reduce((sum, row) => sum + row.weighted_contribution, 0);
  return {
    weighted_score: Number(weightedScore.toFixed(1)),
    max_score: 100,
    weights_found: !!weights,
    industry: dd_industry.selectedOptionValue || "",
    breakdown
  };
}

