  const sortedHighToLow = [...answered].filter(q => !q.error).sort((a, b) => Number(b.final_score || 0) - Number(a.final_score || 0));
  return {
    sme_context: {
      company_name: inp_company_name.text,
      industry: dd_industry.selectedOptionValue,
      subindustry: inp_subindustry.text,
      employee_band: dd_employee_band.selectedOptionValue,
      revenue_band: dd_revenue_band.selectedOptionValue,
      company_location: dd_company_location.selectedOptionValue,
      country: inp_country.text,
      target_market_region: [dd_target_market_1.selectedOptionValue, dd_target_market_2.selectedOptionValue].filter(Boolean),
      target_buyer: dd_target_buyer.selectedOptionValue,
      business_goal: dd_business_goal.selectedOptionValue,
      notes: inp_notes.text
    },
    raw_overall: AssessmentScoring.getOverallScore(),
    weighted_overall: AssessmentScoring.getWeightedOverallScore(),
    category_scores: AssessmentScoring.getCategoryScores(),
    weighted_category_breakdown: AssessmentScoring.getWeightedCategoryBreakdown(),
    category_debug: AssessmentScoring.getCategoryDebug(),
    category_weights: AssessmentScoring.getCategoryWeights(),
    scoring_summary: {
      lowest_scoring_questions: sortedLowToHigh.slice(0, 5),
      highest_scoring_questions: sortedHighToLow.slice(0, 5),
      weakest_categories: [...AssessmentScoring.getCategoryScores() || []].sort((a, b) => Number(a.category_percent || 0) - Number(b.category_percent || 0)).slice(0, 4)
    },
    answered_questions: answered
  };
}

