function () {
  const weighted = AssessmentScoring.getWeightedOverallScore();
  const breakdown = AssessmentScoring.getWeightedCategoryBreakdown();
  const weights = AssessmentScoring.getCategoryWeights();
  const lines = [`Industry: ${weighted.industry || dd_industry.selectedOptionValue || "none"}`, `Category weights found: ${weighted.weights_found}`, `Weighted overall score: ${weighted.weighted_score}/100`, "", `Weights: People=${weights?.people_weight ?? 0}, Governance=${weights?.governance_weight ?? 0}, Community=${weights?.community_weight ?? 0}, Resources=${weights?.resources_weight ?? 0}`, "", "Category-weight calculation:"];
  (breakdown || []).forEach(row => {
    lines.push(`${row.category}: raw ${row.raw_category_percent}% × weight ${row.category_weight} = ${row.weighted_contribution}`);
  });
  return lines.join("\n");
}

