export default {
  isActive(value) {
    // Treat blank as active too, since some live sheets may not have an active column populated
    const raw = String(value ?? "").trim();
    if (raw === "") return true;
    const v = raw.toUpperCase();
    return v === "TRUE" || v === "YES" || v === "1";
  },

  normalizeText(value) {
    return String(value ?? "").trim().toLowerCase();
  },

  getSelectedQuestion() {
    return (QuestionBank.data || []).find(
      q => String(q.question_id) === String(sel_question.selectedOptionValue)
    );
  },

  getSelectedSME() {
    return (NocoDB.data?.list || []).find(
      row => String(row.test_id) === String(sel_test_sme.selectedOptionValue)
    );
  },

  getMetric(question) {
    if (!question?.metric_id) return null;

    const sme = this.getSelectedSME();
    const smeIndustry = this.normalizeText(sme?.industry);

    const matches = (MetricBenchmarks.data || []).filter(
      m =>
        String(m.metric_id) === String(question.metric_id) &&
        this.isActive(m.active)
    );

    if (!matches.length) return null;

    // Prefer industry-specific benchmark row if applicable
    const industryMatch = matches.find(m => {
      const groupType = this.normalizeText(m.benchmark_group_type);
      const groupValue = this.normalizeText(m.benchmark_group_value);
      return groupType === "industry" && groupValue === smeIndustry;
    });

    if (industryMatch) return industryMatch;

    // Then prefer global/all/none rows
    const fallback = matches.find(m => {
      const groupType = this.normalizeText(m.benchmark_group_type);
      const groupValue = this.normalizeText(m.benchmark_group_value);
      return (
        groupType === "global" ||
        groupValue === "all" ||
        groupValue === "none" ||
        groupValue === ""
      );
    });

    return fallback || matches[0];
  },

  getAnswerScaleRow(question, rawAnswer) {
    return (AnswerScales.data || []).find(
      row =>
        String(row.answer_scale_id) === String(question.answer_scale_id) &&
        this.normalizeText(row.answer_option) === this.normalizeText(rawAnswer) &&
        this.isActive(row.active)
    );
  },

  getMethod(metric) {
    return this.normalizeText(
      metric?.scoring_method ||
      metric?.method ||
      metric?.benchmark_method ||
      metric?.benchmark_type ||
      metric?.normalization_method ||
      ""
    );
  },

  toNumber(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : NaN;
  },

  clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  },

  normalize(question, rawAnswer) {
    if (!question) return { error: "No question selected" };

    const responseType = this.normalizeText(question.response_type);

    // CATEGORICAL / BOOLEAN
    if (["categorical", "boolean"].includes(responseType)) {
      const matchedScaleRow = this.getAnswerScaleRow(question, rawAnswer);
      if (!matchedScaleRow) return { error: "No matching answer option found" };

      return {
        value: Number(matchedScaleRow.normalized_score),
        method: "answer_scale"
      };
    }

    // NUMERIC / PERCENT
    if (["numeric", "percent"].includes(responseType)) {
      const x = Number(rawAnswer);
      if (isNaN(x)) return { error: "Invalid numeric input" };

      const metric = this.getMetric(question);
      if (!metric) return { error: "No metric benchmark found" };

      const method = this.getMethod(metric);
      const p1 = this.toNumber(metric.param_1);
      const p2 = this.toNumber(metric.param_2);
      const p3 = this.toNumber(metric.param_3);
      const minValue = this.toNumber(metric.min_value);
      const maxValue = this.toNumber(metric.max_value);
      const safeMax = Number.isFinite(maxValue) && maxValue !== 0 ? maxValue : 100;

      let score01;

      // Direct 0-100 percent
      if (method === "identity_percent" || method === "percent_direct") {
				const capped = this.clamp(x, 0, safeMax);
				return { value: Number(capped.toFixed(2)), method };
			}

      // Boolean metric rows, if ever used directly
      if (method === "identity_boolean") {
        return { value: x, method };
      }

      // Gaussian centered around target mean
      if (method === "gaussian" || method === "gaussian_target") {
        if (isNaN(p1) || isNaN(p2) || p2 === 0) {
          return { error: "Invalid gaussian parameters" };
        }
        const z = (x - p1) / p2;
        score01 = Math.exp(-0.5 * Math.pow(z, 2));
        return { value: Number((score01 * safeMax).toFixed(2)), method };
      }

      // Linear cap: full marks at threshold and above
      if (method === "linear_cap" || method === "linear_cap_benchmark") {
        if (isNaN(p1) || p1 === 0) {
          return { error: "Invalid linear_cap threshold" };
        }
        score01 = Math.min(x / p1, 1);
        return { value: Number((score01 * safeMax).toFixed(2)), method };
      }

      // Inverse count: 100/(1+x)
      if (method === "inverse_count") {
        score01 = 1 / (1 + x);
        return { value: Number((score01 * safeMax).toFixed(2)), method };
      }

      // Inverse percentage: 100-x
      if (method === "inverse_percentage" || method === "percent_inverse") {
				const cappedInput = this.clamp(x, 0, 100);
				score01 = 1 - (cappedInput / 100);
				score01 = this.clamp(score01, 0, 1);
				return { value: Number((score01 * 100).toFixed(2)), method };
			}

      // Benchmark inverse ratio: 100/(1+x/mu)
      if (method === "benchmark_inverse_ratio" || method === "benchmark_ratio_inverse") {
        if (isNaN(p1) || p1 === 0) {
          return { error: "Invalid benchmark parameter" };
        }
        score01 = 1 / (1 + (x / p1));
        return { value: Number((score01 * safeMax).toFixed(2)), method };
      }

      // Exponential decay threshold
      if (method === "exponential_decay" || method === "exponential_decay_threshold") {
				if (isNaN(p1)) {
					return { error: "Invalid exponential decay parameter" };
				}

				const k = !isNaN(p2) && p2 !== 0 ? p2 : 10;

				// For percent questions, interpret whole-number input like 14 as 14% = 0.14
				const xAdjusted =
					responseType === "percent" || String(metric.unit || "").toLowerCase().includes("percent")
						? x / 100
						: x;

				const threshold =
					p1 > 1 && (responseType === "percent" || String(metric.unit || "").toLowerCase().includes("percent"))
						? p1 / 100
						: p1;

				if (xAdjusted <= threshold) {
					score01 = 1;
				} else {
					score01 = Math.exp(-k * (xAdjusted - threshold));
					score01 = this.clamp(score01, 0, 1);
				}

				return { value: Number((score01 * safeMax).toFixed(2)), method };
			}

      // Inverse linear cap: best at 0, worst at threshold/max
      if (method === "inverse_linear_cap") {
        const cap = !isNaN(p2) && p2 !== 0
          ? p2
          : (!isNaN(maxValue) && maxValue !== 0 ? maxValue : p1);

        if (isNaN(cap) || cap === 0) {
          return { error: "Invalid inverse_linear_cap parameters" };
        }

        score01 = 1 - Math.min(x / cap, 1);
        score01 = this.clamp(score01, 0, 1);
        return { value: Number((score01 * safeMax).toFixed(2)), method };
      }

      // Banded scoring using param_1 / param_2 / param_3
      // lower is better:
      // x <= p1 => 100
      // p1 < x <= p2 => 75
      // p2 < x <= p3 => 50
      // x > p3 => 0
      if (method === "banded") {
        if (isNaN(p1) || isNaN(p2) || isNaN(p3)) {
          return { error: "Invalid banded parameters" };
        }

        let value;
        if (x <= p1) value = 100;
        else if (x <= p2) value = 75;
        else if (x <= p3) value = 50;
        else value = 0;

        return { value, method };
      }

      // Min-max fallback
      if (method === "min_max") {
        if (isNaN(minValue) || isNaN(maxValue) || maxValue === minValue) {
          return { error: "Invalid min_max parameters" };
        }
        score01 = (x - minValue) / (maxValue - minValue);
        score01 = this.clamp(score01, 0, 1);
        return { value: Number((score01 * 100).toFixed(2)), method };
      }

      return { error: "Unsupported metric method: " + method };
    }

    return { error: "Unsupported response type: " + responseType };
  },

  getNormalizedScore() {
    const question = this.getSelectedQuestion();
    const result = this.normalize(question, inp_manual_answer.text);
    return result.error || result.value;
  },

  getWeightedScore() {
    const question = this.getSelectedQuestion();
    if (!question) return "No question selected";

    const baseWeight = Number(question.base_weight);
    if (isNaN(baseWeight)) return "Invalid base weight";

    const result = this.normalize(question, inp_manual_answer.text);
    if (result.error) return result.error;

    return Number((result.value * baseWeight).toFixed(2));
  },

  getFinalMultiplier() {
    const question = this.getSelectedQuestion();
    const sme = this.getSelectedSME();

    if (!question) return { error: "No question selected" };
    if (!sme) return { error: "No SME selected" };

    const questionTags = String(question.tags || "")
      .split(/[;,]/)
      .map(s => s.trim().toLowerCase())
      .filter(Boolean);

    const questionCategory = this.normalizeText(question.category);
    const questionSubcategory = this.normalizeText(question.subcategory);

    const smeIndustry = this.normalizeText(sme.industry);
    const smeRegion = this.normalizeText(sme.target_market_region);
    const smeBuyer = this.normalizeText(sme.target_buyer);
    const smeGoal = this.normalizeText(sme.business_goal);

    const matches = (MultiplierRules.data || []).filter(rule => {
      const rawActive = String(rule.active ?? "").trim().toUpperCase();
			if (!(rawActive === "TRUE" || rawActive === "YES" || rawActive === "1")) return false;

      const ruleTag = this.normalizeText(rule.tag);
      const ruleCategory = this.normalizeText(rule.category);
      const ruleSubcategory = this.normalizeText(rule.subcategory);
      const ruleIndustry = this.normalizeText(rule.industry);
      const ruleRegion = this.normalizeText(rule.target_market_region);
      const ruleBuyer = this.normalizeText(rule.target_buyer);
      const ruleGoal = this.normalizeText(rule.business_goal);

      const tagOk = ruleTag === "" || ruleTag === "any" || questionTags.includes(ruleTag);
      const categoryOk = ruleCategory === "" || ruleCategory === "any" || ruleCategory === questionCategory;
      const subcategoryOk = ruleSubcategory === "" || ruleSubcategory === "any" || ruleSubcategory === questionSubcategory;
      const industryOk = ruleIndustry === "" || ruleIndustry === "any" || ruleIndustry === smeIndustry;
      const regionOk = ruleRegion === "" || ruleRegion === "any" || smeRegion.includes(ruleRegion);
      const buyerOk = ruleBuyer === "" || ruleBuyer === "any" || smeBuyer.includes(ruleBuyer);
      const goalOk = ruleGoal === "" || ruleGoal === "any" || smeGoal.includes(ruleGoal);

      return tagOk && categoryOk && subcategoryOk && industryOk && regionOk && buyerOk && goalOk;
    });

    const rawMultiplier = matches.reduce((acc, rule) => {
      const m = Number(rule.multiplier);
      return acc * (isNaN(m) ? 1 : m);
    }, 1);

    return { value: Math.min(rawMultiplier, 1.5) };
  },

  getFinalScore() {
    const weighted = this.getWeightedScore();
    if (typeof weighted !== "number") return weighted;

    const mult = this.getFinalMultiplier();
    if (mult.error) return mult.error;

    return Number((weighted * mult.value).toFixed(2));
  }
};

