export default {
  isActive(value) {
    const raw = String(value ?? "").trim();
    if (raw === "") return true;
    const v = raw.toUpperCase();
    return v === "TRUE" || v === "YES" || v === "1";
  },

  normalizeText(value) {
    return String(value ?? "").trim().toLowerCase();
  },

  toNumber(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : NaN;
  },

  clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  },

  getSelectedSME() {
    return {
      company_name: inp_company_name.text,
      industry: dd_industry.selectedOptionValue,
      subindustry: inp_subindustry.text,
			employee_band: dd_employee_band.selectedOptionValue,
			revenue_band: dd_revenue_band.selectedOptionValue,
      company_location: dd_company_location.selectedOptionValue,
      country: inp_country.text,
      target_market_region: [
        dd_target_market_1.selectedOptionValue,
        dd_target_market_2.selectedOptionValue
      ].filter(Boolean).join(", "),
      target_buyer: dd_target_buyer.selectedOptionValue,
      business_goal: dd_business_goal.selectedOptionValue,
      notes: inp_notes.text
    };
  },

  getAnswerScaleRow(question, rawAnswer) {
    return (AnswerScales.data || []).find(
      row =>
        String(row.answer_scale_id || "").trim() === String(question.answer_scale_id || "").trim() &&
        this.normalizeText(row.answer_option) === this.normalizeText(rawAnswer) &&
        this.isActive(row.active)
    );
  },

  getMethod(metric) {
    return this.normalizeText(
      metric?.scoring_method ||
      metric?.method ||
      metric?.benchmark_method ||
      metric?.benchmark_type ||
      metric?.normalization_method ||
      ""
    );
  },

  getMetric(question) {
    if (!question?.metric_id) return null;

    const sme = this.getSelectedSME();
    const smeIndustry = this.normalizeText(sme?.industry);

    const matches = (MetricBenchmarks.data || []).filter(
      m =>
        String(m.metric_id) === String(question.metric_id) &&
        this.isActive(m.active)
    );

    if (!matches.length) return null;

    const industryMatch = matches.find(m => {
      const groupType = this.normalizeText(m.benchmark_group_type);
      const groupValue = this.normalizeText(m.benchmark_group_value);
      return groupType === "industry" && groupValue === smeIndustry;
    });

    if (industryMatch) return industryMatch;

    const fallback = matches.find(m => {
      const groupType = this.normalizeText(m.benchmark_group_type);
      const groupValue = this.normalizeText(m.benchmark_group_value);
      return (
        groupType === "global" ||
        groupValue === "all" ||
        groupValue === "none" ||
        groupValue === ""
      );
    });

    return fallback || matches[0];
  },

  normalize(question, rawAnswer) {
  if (!question) return { error: "No question provided" };

  const responseType = this.normalizeText(question.response_type);

  if (rawAnswer === null || rawAnswer === undefined || String(rawAnswer).trim() === "") {
    return { error: "No answer provided" };
  }

  if (["categorical", "boolean"].includes(responseType)) {
    const matchedScaleRow = this.getAnswerScaleRow(question, rawAnswer);
    if (!matchedScaleRow) return { error: "No matching answer option found" };

    return {
      value: Number(matchedScaleRow.normalized_score),
      method: "answer_scale"
    };
  }

  if (["numeric", "percent"].includes(responseType)) {
    const x = Number(rawAnswer);
    if (isNaN(x)) return { error: "Invalid numeric input" };

    const metric = this.getMetric(question);
    if (!metric) return { error: "No metric benchmark found" };

    const method = this.getMethod(metric);
    const p1 = this.toNumber(metric.param_1);
    const p2 = this.toNumber(metric.param_2);
    const p3 = this.toNumber(metric.param_3);
    const minValue = this.toNumber(metric.min_value);
    const maxValue = this.toNumber(metric.max_value);
    const safeMax = Number.isFinite(maxValue) && maxValue !== 0 ? maxValue : 100;

    let score01;

    if (method === "identity_percent" || method === "percent_direct") {
      const capped = this.clamp(x, 0, safeMax);
      return { value: Number(capped.toFixed(2)), method };
    }

    if (method === "identity_boolean") {
      return { value: x, method };
    }

    if (method === "gaussian" || method === "gaussian_target") {
      if (isNaN(p1) || isNaN(p2) || p2 === 0) {
        return { error: "Invalid gaussian parameters" };
      }
      const z = (x - p1) / p2;
      score01 = Math.exp(-0.5 * Math.pow(z, 2));
      return { value: Number((score01 * safeMax).toFixed(2)), method };
    }

    if (method === "linear_cap" || method === "linear_cap_benchmark") {
      if (isNaN(p1) || p1 === 0) {
        return { error: "Invalid linear_cap threshold" };
      }
      score01 = Math.min(x / p1, 1);
      return { value: Number((score01 * safeMax).toFixed(2)), method };
    }

    if (method === "inverse_count") {
      score01 = 1 / (1 + x);
      return { value: Number((score01 * safeMax).toFixed(2)), method };
    }

    if (method === "inverse_percentage" || method === "percent_inverse") {
      const cappedInput = this.clamp(x, 0, 100);
      score01 = 1 - cappedInput / 100;
      score01 = this.clamp(score01, 0, 1);
      return { value: Number((score01 * 100).toFixed(2)), method };
    }

    if (method === "benchmark_inverse_ratio" || method === "benchmark_ratio_inverse") {
      if (isNaN(p1) || p1 === 0) {
        return { error: "Invalid benchmark parameter" };
      }
      score01 = 1 / (1 + x / p1);
      return { value: Number((score01 * safeMax).toFixed(2)), method };
    }

    if (method === "exponential_decay" || method === "exponential_decay_threshold") {
      if (isNaN(p1)) {
        return { error: "Invalid exponential decay parameter" };
      }

      const k = !isNaN(p2) && p2 !== 0 ? p2 : 10;

      const xAdjusted =
        responseType === "percent" || String(metric.unit || "").toLowerCase().includes("percent")
          ? x / 100
          : x;

      const threshold =
        p1 > 1 && (responseType === "percent" || String(metric.unit || "").toLowerCase().includes("percent"))
          ? p1 / 100
          : p1;

      score01 = xAdjusted <= threshold
        ? 1
        : Math.exp(-k * (xAdjusted - threshold));

      score01 = this.clamp(score01, 0, 1);
      return { value: Number((score01 * safeMax).toFixed(2)), method };
    }

    if (method === "inverse_linear_cap") {
      const cap = !isNaN(p2) && p2 !== 0
        ? p2
        : (!isNaN(maxValue) && maxValue !== 0 ? maxValue : p1);

      if (isNaN(cap) || cap === 0) {
        return { error: "Invalid inverse_linear_cap parameters" };
      }

      score01 = 1 - Math.min(x / cap, 1);
      score01 = this.clamp(score01, 0, 1);
      return { value: Number((score01 * safeMax).toFixed(2)), method };
    }

    if (method === "banded") {
      if (isNaN(p1) || isNaN(p2) || isNaN(p3)) {
        return { error: "Invalid banded parameters" };
      }

      let value;
      if (x <= p1) value = 100;
      else if (x <= p2) value = 75;
      else if (x <= p3) value = 50;
      else value = 0;

      return { value, method };
    }

    if (method === "min_max") {
      if (isNaN(minValue) || isNaN(maxValue) || maxValue === minValue) {
        return { error: "Invalid min_max parameters" };
      }

      score01 = (x - minValue) / (maxValue - minValue);
      score01 = this.clamp(score01, 0, 1);
      return { value: Number((score01 * 100).toFixed(2)), method };
    }

    return { error: "Unsupported metric method: " + method };
  }

  return { error: "Unsupported response type: " + responseType };
},

  getFinalMultiplierForQuestion(question) {
  const sme = this.getSelectedSME();

  if (!question) return { error: "No question selected" };
  if (!sme) return { error: "No SME selected" };

  const questionTags = Array.isArray(question.tags)
    ? question.tags.map(t => String(t).trim().toLowerCase()).filter(Boolean)
    : String(question.tags || "")
        .split(/[;,]/)
        .map(s => s.trim().toLowerCase())
        .filter(Boolean);

  const questionCategory = this.normalizeText(question.category);
  const questionSubcategory = this.normalizeText(question.subcategory);

  const smeIndustry = this.normalizeText(sme.industry);
  const smeRegion = this.normalizeText(sme.target_market_region);
  const smeBuyer = this.normalizeText(sme.target_buyer);
  const smeGoal = this.normalizeText(sme.business_goal);

  const matches = (MultiplierRules.data || []).filter(rule => {
    const rawActive = String(rule.active ?? "").trim().toUpperCase();
    if (!(rawActive === "TRUE" || rawActive === "YES" || rawActive === "1")) return false;

    const ruleTags = String(rule.tag || "")
			.split(/[;,]/)
			.map(s => s.trim().toLowerCase())
			.filter(Boolean);
    const ruleCategory = this.normalizeText(rule.category);
    const ruleSubcategory = this.normalizeText(rule.subcategory);
    const ruleIndustry = this.normalizeText(rule.industry);
    const ruleRegion = this.normalizeText(rule.target_market_region);
    const ruleBuyer = this.normalizeText(rule.target_buyer);
    const ruleGoal = this.normalizeText(rule.business_goal);

    const tagOk =
			ruleTags.length === 0 ||
			ruleTags.includes("any") ||
			ruleTags.some(rt => questionTags.includes(rt));
    const categoryOk = ruleCategory === "" || ruleCategory === "any" || ruleCategory === questionCategory;
    const subcategoryOk = ruleSubcategory === "" || ruleSubcategory === "any" || ruleSubcategory === questionSubcategory;
    const industryOk = ruleIndustry === "" || ruleIndustry === "any" || ruleIndustry === smeIndustry;
    const regionOk = ruleRegion === "" || ruleRegion === "any" || smeRegion.includes(ruleRegion);
    const buyerOk = ruleBuyer === "" || ruleBuyer === "any" || smeBuyer.includes(ruleBuyer);
    const goalOk = ruleGoal === "" || ruleGoal === "any" || smeGoal.includes(ruleGoal);

    return tagOk && categoryOk && subcategoryOk && industryOk && regionOk && buyerOk && goalOk;
  });

  const rawMultiplier = matches.reduce((acc, rule) => {
    const m = Number(rule.multiplier);
    return acc * (isNaN(m) ? 1 : m);
  }, 1);

  return {
    value: Math.min(rawMultiplier, 1.5),
    matched_rules: matches.map(rule => ({
      rule_id: rule.rule_id,
      tag: rule.tag,
      category: rule.category,
      subcategory: rule.subcategory,
      industry: rule.industry,
      target_market_region: rule.target_market_region,
      target_buyer: rule.target_buyer,
      business_goal: rule.business_goal,
      multiplier: rule.multiplier
    }))
  };
},

  getQuestionDebug(question, rawAnswer) {
    if (!question) return { error: "No question provided" };

    const normalized = this.normalize(question, rawAnswer);
    if (normalized.error) {
      return {
        question_id: question.question_id,
        question_text: question.question_text,
        category: question.category,
        raw_answer: rawAnswer,
        error: normalized.error
      };
    }

    const baseWeight = Number(question.base_weight);
    if (isNaN(baseWeight)) {
      return {
        question_id: question.question_id,
        question_text: question.question_text,
        category: question.category,
        raw_answer: rawAnswer,
        normalized_score: normalized.value,
        normalization_method: normalized.method,
        error: "Invalid base weight"
      };
    }

    const weighted = Number((normalized.value * baseWeight).toFixed(2));
    const mult = this.getFinalMultiplierForQuestion(question);

    if (mult.error) {
      return {
        question_id: question.question_id,
        question_text: question.question_text,
        category: question.category,
        raw_answer: rawAnswer,
        normalized_score: normalized.value,
        normalization_method: normalized.method,
        base_weight: baseWeight,
        weighted_score: weighted,
        error: mult.error
      };
    }

    const totalPossible = Number((100 * baseWeight * mult.value).toFixed(2));

    return {
      question_id: question.question_id,
      question_text: question.question_text,
      category: question.category || "Uncategorized",
      raw_answer: rawAnswer,
      normalized_score: normalized.value,
      normalization_method: normalized.method,
      base_weight: baseWeight,
      weighted_score: weighted,
      multiplier: mult.value,
      matched_rules: mult.matched_rules,
      final_score: Number((weighted * mult.value).toFixed(2)),
      total_possible: totalPossible,
      completion_percent: totalPossible > 0
        ? Number((((weighted * mult.value) / totalPossible) * 100).toFixed(1))
        : null
    };
  },

  getAllAnsweredQuestionDebug() {
    const questions = API_Get_Questions.data?.questions || [];
    const answers = appsmith.store.answers || {};

    return questions
      .map(question => {
        const rawAnswer = answers[question.question_id];
        return this.getQuestionDebug(question, rawAnswer);
      })
      .filter(row => String(row.raw_answer ?? "").trim() !== "");
  },

  getCategoryScores() {
    const rows = this.getAllAnsweredQuestionDebug();
    const grouped = {};

    rows.forEach(row => {
      if (row.error) return;

      const category = row.category || "Uncategorized";

      if (!grouped[category]) {
        grouped[category] = {
          category,
          points_earned: 0,
          total_possible: 0,
          questions_answered: 0
        };
      }

      grouped[category].points_earned += Number(row.final_score || 0);
      grouped[category].total_possible += Number(row.total_possible || 0);
      grouped[category].questions_answered += 1;
    });

    return Object.values(grouped).map(cat => ({
      category: cat.category,
      points_earned: Number(cat.points_earned.toFixed(2)),
      total_possible: Number(cat.total_possible.toFixed(2)),
      category_percent: cat.total_possible > 0
        ? Number(((cat.points_earned / cat.total_possible) * 100).toFixed(1))
        : null,
      questions_answered: cat.questions_answered
    }));
  },

  getOverallScore() {
    const categories = this.getCategoryScores();

    const pointsEarned = categories.reduce((sum, row) => sum + Number(row.points_earned || 0), 0);
    const totalPossible = categories.reduce((sum, row) => sum + Number(row.total_possible || 0), 0);

    return {
      points_earned: Number(pointsEarned.toFixed(2)),
      total_possible: Number(totalPossible.toFixed(2)),
      overall_percent: totalPossible > 0
        ? Number(((pointsEarned / totalPossible) * 100).toFixed(1))
        : null,
      categories_answered: categories.length
    };
  },

	getCategoryDebug() {
		const rows = this.getAllAnsweredQuestionDebug();
		const grouped = {};

		rows.forEach(row => {
			if (row.error) return;

			const category = row.category || "Uncategorized";

			if (!grouped[category]) {
				grouped[category] = [];
			}

			grouped[category].push({
				question_id: row.question_id,
				answer: row.raw_answer,
				base_weight: row.base_weight,
				multiplier: row.multiplier,
				final_score: row.final_score
			});
		});

		return grouped;
	},

	getCategoryWeights() {
		const industry = dd_industry.selectedOptionValue;
		const rows = CategoryWeights.data || [];

		if (!industry || !Array.isArray(rows) || !rows.length) return null;

		const row = rows.find(r => String(r.industry || "").trim() === String(industry).trim());
		if (!row) return null;

		return {
			industry: row.industry,
			people_weight: Number(row.people_weight || 0),
			governance_weight: Number(row.governance_weight || 0),
			community_weight: Number(row.community_weight || 0),
			resources_weight: Number(row.resources_weight || 0),
			notes: row.notes || ""
		};
	},

	getCategoryByName(name) {
		const cats = this.getCategoryScores();
		return cats.find(c => String(c.category) === String(name));
	},

	getWeightedOverallScore() {
		const weights = this.getCategoryWeights();
		const categories = this.getCategoryScores();

		if (!categories || !categories.length) {
			return {
				weighted_score: 0,
				max_score: 100,
				weights_found: false,
				industry: dd_industry.selectedOptionValue || "",
				breakdown: []
			};
		}

		const weightMap = {
			People: weights?.people_weight ?? 0,
			Governance: weights?.governance_weight ?? 0,
			Community: weights?.community_weight ?? 0,
			Resources: weights?.resources_weight ?? 0
		};

		const breakdown = categories.map(c => {
			const percent = Number(c.category_percent || 0);
			const weight = Number(weightMap[c.category] || 0);
			const contribution = percent * weight;

			return {
				category: c.category,
				raw_percent: percent,
				weight: weight,
				weighted_contribution: contribution
			};
		});

		const weightedScore = breakdown.reduce((sum, row) => sum + row.weighted_contribution, 0);

		return {
			weighted_score: Number(weightedScore.toFixed(1)),
			max_score: 100,
			weights_found: !!weights,
			industry: dd_industry.selectedOptionValue || "",
			breakdown
		};
	},

	getWeightedCategoryBreakdown() {
		const categories = this.getCategoryScores();
		const weights = this.getCategoryWeights();

		const weightMap = {
			People: Number(weights?.people_weight || 0),
			Governance: Number(weights?.governance_weight || 0),
			Community: Number(weights?.community_weight || 0),
			Resources: Number(weights?.resources_weight || 0)
		};

		return (categories || []).map(cat => {
			const rawPercent = Number(cat.category_percent || 0);
			const weight = Number(weightMap[cat.category] || 0);
			const weightedContribution = Number((rawPercent * weight).toFixed(2));

			return {
				category: cat.category,
				points_earned: cat.points_earned,
				total_possible: cat.total_possible,
				raw_category_percent: rawPercent,
				category_weight: weight,
				weighted_contribution: weightedContribution,
				questions_answered: cat.questions_answered
			};
		});
	},

	getBenchmarkDebug(question) {
  if (!question) return "Benchmark: no question";

  const responseType = this.normalizeText(question.response_type);

  if (["categorical", "boolean"].includes(responseType)) {
    return `Benchmark/formula: AnswerScale lookup | answer_scale_id=${question.answer_scale_id || "none"}`;
  }

  const metric = this.getMetric(question);
  if (!metric) return "Benchmark/formula: no MetricBenchmarks row found";

  const method = this.getMethod(metric);

  const params = {
    metric_id: metric.metric_id || question.metric_id || "",
    group_type: metric.benchmark_group_type || "",
    group_value: metric.benchmark_group_value || "",
    unit: metric.unit || "",
    method,
    param_1: metric.param_1 ?? "",
    param_2: metric.param_2 ?? "",
    param_3: metric.param_3 ?? "",
    min_value: metric.min_value ?? "",
    max_value: metric.max_value ?? ""
  };

  const formulaMap = {
    identity_percent: "score = clamp(x, 0, max)",
    percent_direct: "score = clamp(x, 0, max)",
    gaussian: "score = exp(-0.5 * ((x - p1) / p2)^2) * max",
    gaussian_target: "score = exp(-0.5 * ((x - p1) / p2)^2) * max",
    linear_cap: "score = min(x / p1, 1) * max",
    linear_cap_benchmark: "score = min(x / p1, 1) * max",
    inverse_count: "score = 1 / (1 + x) * max",
    inverse_percentage: "score = (1 - clamp(x,0,100)/100) * 100",
    percent_inverse: "score = (1 - clamp(x,0,100)/100) * 100",
    benchmark_inverse_ratio: "score = 1 / (1 + x / p1) * max",
    benchmark_ratio_inverse: "score = 1 / (1 + x / p1) * max",
    exponential_decay: "if x <= p1: score=max; else score=exp(-p2*(x-p1))*max",
    exponential_decay_threshold: "if x <= p1: score=max; else score=exp(-p2*(x-p1))*max",
    inverse_linear_cap: "score = (1 - min(x / cap, 1)) * max",
    banded: "x<=p1:100 | <=p2:75 | <=p3:50 | else:0",
    min_max: "score = clamp((x-min)/(max-min),0,1)*100"
  };

  return [
    `Benchmark/formula: ${formulaMap[method] || "unsupported/unknown method"}`,
    `Metric: ${params.metric_id}`,
    `Group: ${params.group_type}:${params.group_value}`,
    `Unit: ${params.unit || "none"}`,
    `Method: ${params.method || "none"}`,
    `Params: p1=${params.param_1}, p2=${params.param_2}, p3=${params.param_3}, min=${params.min_value}, max=${params.max_value}`
  ].join("\n");
},

getQuestionDebugText(question, rawAnswer) {
  const d = this.getQuestionDebug(question, rawAnswer);

  if (!d) return "No debug data";
  if (d.error) {
    return [
      `Q: ${question?.question_id || "unknown"}`,
      `Answer: ${rawAnswer ?? "blank"}`,
      `ERROR: ${d.error}`,
      this.getBenchmarkDebug(question)
    ].join("\n");
  }

  const matchedRules = (d.matched_rules || [])
    .map(r => `${r.rule_id || "rule"} (${r.multiplier || 1}x)`)
    .join(", ") || "none";

  return [
    `Q: ${d.question_id}`,
    `Answer: ${d.raw_answer}`,
    `Normalized score: ${d.normalized_score}/100`,
    `Normalization method: ${d.normalization_method}`,
    `Base weight: ${d.base_weight}`,
    `Weighted score: ${d.weighted_score}`,
    `Multiplier: ${d.multiplier}`,
    `Matched multiplier rules: ${matchedRules}`,
    `Final score: ${d.final_score} / ${d.total_possible}`,
    `Completion: ${d.completion_percent}%`,
    this.getBenchmarkDebug(question)
  ].join("\n");
},

getCategoryWeightsDebugText() {
  const weighted = this.getWeightedOverallScore();
  const breakdown = this.getWeightedCategoryBreakdown();
  const weights = this.getCategoryWeights();

  const lines = [
    `Industry: ${weighted.industry || dd_industry.selectedOptionValue || "none"}`,
    `Category weights found: ${weighted.weights_found}`,
    `Weighted overall score: ${weighted.weighted_score}/100`,
    "",
    `Weights: People=${weights?.people_weight ?? 0}, Governance=${weights?.governance_weight ?? 0}, Community=${weights?.community_weight ?? 0}, Resources=${weights?.resources_weight ?? 0}`,
    "",
    "Category-weight calculation:"
  ];

  (breakdown || []).forEach(row => {
    lines.push(
      `${row.category}: raw ${row.raw_category_percent}% × weight ${row.category_weight} = ${row.weighted_contribution}`
    );
  });

  return lines.join("\n");
},

	getParsedRecommendations() {
		try {
			const raw = API_Get_Recommendations.data?.output?.[0]?.content?.[0]?.text;
			if (!raw) return null;
			return JSON.parse(raw);
		} catch (e) {
			return null;
		}
	},

	getScorePayload() {
		const answered = this.getAllAnsweredQuestionDebug() || [];
		const sortedLowToHigh = [...answered]
			.filter(q => !q.error)
			.sort((a, b) => Number(a.final_score || 0) - Number(b.final_score || 0));

		const sortedHighToLow = [...answered]
			.filter(q => !q.error)
			.sort((a, b) => Number(b.final_score || 0) - Number(a.final_score || 0));

		return {
			sme_context: {
				company_name: inp_company_name.text,
				industry: dd_industry.selectedOptionValue,
				subindustry: inp_subindustry.text,
				employee_band: dd_employee_band.selectedOptionValue,
				revenue_band: dd_revenue_band.selectedOptionValue,
				company_location: dd_company_location.selectedOptionValue,
				country: inp_country.text,
				target_market_region: [
					dd_target_market_1.selectedOptionValue,
					dd_target_market_2.selectedOptionValue
				].filter(Boolean),
				target_buyer: dd_target_buyer.selectedOptionValue,
				business_goal: dd_business_goal.selectedOptionValue,
				notes: inp_notes.text
			},
			raw_overall: this.getOverallScore(),
			weighted_overall: this.getWeightedOverallScore(),
			category_scores: this.getCategoryScores(),
			weighted_category_breakdown: this.getWeightedCategoryBreakdown(),
			category_debug: this.getCategoryDebug(),
			category_weights: this.getCategoryWeights(),
			scoring_summary: {
				lowest_scoring_questions: sortedLowToHigh.slice(0, 5),
				highest_scoring_questions: sortedHighToLow.slice(0, 5),
				weakest_categories: [...(this.getCategoryScores() || [])]
					.sort((a, b) => Number(a.category_percent || 0) - Number(b.category_percent || 0))
					.slice(0, 4)
			},
			answered_questions: answered
		};
	},
};

