export default {
  steps: [
    "Calculating scores",
    "Formatting payload",
    "Searching knowledge bank",
    "Finding chunks",
    "Building recommendation prompt",
    "Prompting agent",
    "Analyzing agent response",
    "Formatting output"
  ],

  async startLoading() {
    try {
      this.stopLoading();
    } catch (e) {}

    storeValue("recLoading", true, false);
    storeValue("recStepIndex", 0, false);

    const id = setInterval(() => {
      const current = Number(appsmith.store.recStepIndex || 0);
      const next = (current + 1) % this.steps.length;
      storeValue("recStepIndex", next, false);
    }, 3500);

    storeValue("recLoadingIntervalId", id, false);
  },

  stopLoading() {
    const id = appsmith.store.recLoadingIntervalId;
    if (id) clearInterval(id);

    storeValue("recLoadingIntervalId", null, false);
    storeValue("recLoading", false, false);
  },

  getCurrentStepLabel() {
    const idx = Number(appsmith.store.recStepIndex || 0);
    return this.steps[idx] || this.steps[0];
  },

  getCurrentStepNumber() {
    return Number(appsmith.store.recStepIndex || 0) + 1;
  },

  getLoadingStepsForList() {
    const idx = Number(appsmith.store.recStepIndex || 0);

    return this.steps.map((label, i) => ({
      number: i + 1,
      label,
      state: i < idx ? "done" : i === idx ? "active" : "pending"
    }));
  },

  getWeightedCategoryBars() {
    const rows = AssessmentScoring.getWeightedCategoryBreakdown() || [];

    return rows.map((row) => ({
      category: row.category,
      normalized_score: Number(row.raw_category_percent || 0),
      weighted_contribution: Number(row.weighted_contribution || 0),
      category_weight: Number(row.category_weight || 0)
    }));
  },

	resetAssessmentPage() {
		try {
			const id = appsmith.store.recLoadingIntervalId;
			if (id) clearInterval(id);
		} catch (e) {}

		storeValue("showScores", false, false);
		storeValue("startedAssessment", false, false);
		storeValue("scoredPayload", null, false);
		storeValue("answersDraft", {}, false);
		storeValue("recLoading", false, false);
		storeValue("recStepIndex", 0, false);
		storeValue("recLoadingIntervalId", null, false);
	},

  getWeightedCategoryChartOption() {
    const rows = this.getWeightedCategoryBars();

    return {
      animation: true,
      animationDuration: 2000,
      animationEasing: "cubicOut",
      grid: {
        left: 40,
        right: 20,
        top: 40,
        bottom: 40
      },
      tooltip: {
        trigger: "axis",
        axisPointer: {
          type: "shadow"
        },
        formatter: function(params) {
          const p = params[0];
          const row = rows[p.dataIndex];
          return (
            `<b>${row.category}</b><br/>` +
            `Normalized score: ${row.normalized_score}%<br/>` +
            `Weighted contribution: ${row.weighted_contribution}<br/>` +
            `Category weight: ${row.category_weight}`
          );
        }
      },
      xAxis: {
        type: "category",
        data: rows.map(r => r.category)
      },
      yAxis: {
        type: "value",
        min: 0,
        max: 100,
        name: "Score (%)"
      },
      series: [
        {
          type: "bar",
          data: rows.map(r => r.normalized_score),
          barWidth: "45%",
          label: {
            show: true,
            position: "top",
            formatter: "{c}%"
          }
        }
      ]
    };
  }
};

